import{_ as i,o as t,c as a,a2 as e}from"./chunks/framework.CCCdsIgc.js";const c=JSON.parse('{"title":"在 IDE 里用","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ide.md","filePath":"guide/ide.md"}'),n={name:"guide/ide.md"};function l(d,s,o,h,p,k){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="在-ide-里用" tabindex="-1">在 IDE 里用 <a class="header-anchor" href="#在-ide-里用" aria-label="Permalink to &quot;在 IDE 里用&quot;">​</a></h1><p>FlyknitBuddy 可以作为 AI 助手接进 <strong>VS Code、Zed、JetBrains（IntelliJ IDEA、PyCharm 等）</strong>，在编辑器旁边的面板里对话、看它改文件和跑命令。用的是 ACP（Agent Client Protocol）标准，背后是同一个 <code>flyknit.exe</code>。</p><p>前提和 <a href="/help/guide/terminal.html#开始之前">终端对话</a> 一样：IT 打开「命令行 / IDE 接入」、这台电脑登录过 FlyknitBuddy。</p><h2 id="vs-code" tabindex="-1">VS Code <a class="header-anchor" href="#vs-code" aria-label="Permalink to &quot;VS Code&quot;">​</a></h2><p><strong>1. 装 ACP 插件</strong></p><p>在扩展商店搜索 <code>ACP</code>，装一个 ACP 客户端插件（如「ACP Client」「ACP — Agent Client Protocol」）。</p><p><strong>2. 找到 flyknit.exe 的完整路径</strong></p><p>正式安装的一般是 <code>C:\\Program Files\\FlyknitBuddy\\flyknit.exe</code>。不确定时在命令行里运行：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">where</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> flyknit</span></span></code></pre></div><p><strong>3. 在用户设置里加上 FlyknitBuddy</strong></p><p>按 <code>Ctrl+Shift+P</code> → 输入「Open User Settings (JSON)」，加一段（路径换成第 2 步看到的，<code>\\</code> 要写成 <code>\\\\</code>）：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;agent_servers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;FlyknitBuddy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Program Files</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">FlyknitBuddy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">flyknit.exe&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;cwd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${workspaceFolder}&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>不同插件的配置项名称可能不同（比如 <code>acp.agents</code>），以插件说明为准；关键是三样：程序路径、参数 <code>acp</code>、工作目录是当前项目。</p><p><strong>4. 完全退出 VS Code 再打开</strong></p><p>VS Code 只在启动时读一次配置和 PATH。重开后在插件的面板里选 FlyknitBuddy 开始对话。</p><div class="tip custom-block"><p class="custom-block-title">一定要写完整路径</p><p>插件提示「FlyknitBuddy not installed」「找不到命令」，几乎都是 <code>command</code> 只写了 <code>flyknit</code>。写成带 <code>.exe</code> 的完整路径即可。</p></div><h2 id="zed" tabindex="-1">Zed <a class="header-anchor" href="#zed" aria-label="Permalink to &quot;Zed&quot;">​</a></h2><p><code>settings.json</code>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;agent_servers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;FlyknitBuddy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;custom&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;flyknit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="jetbrains" tabindex="-1">JetBrains <a class="header-anchor" href="#jetbrains" aria-label="Permalink to &quot;JetBrains&quot;">​</a></h2><p>按 JetBrains 的说明添加一个自定义 ACP 智能体（不同版本入口位置不同）：命令填 <code>flyknit.exe</code> 的完整路径，参数填 <code>acp</code>。</p><h2 id="在-ide-里用起来是什么样" tabindex="-1">在 IDE 里用起来是什么样 <a class="header-anchor" href="#在-ide-里用起来是什么样" aria-label="Permalink to &quot;在 IDE 里用起来是什么样&quot;">​</a></h2><ul><li><strong>工作区</strong>就是 IDE 打开的项目文件夹。</li><li><strong>确认</strong>：需要确认的操作由 IDE 弹出确认框（有的插件显示在窗口顶部中间）。普通写入有「允许一次 / 总是允许 / 拒绝」，删除、覆盖这类高危操作只有「允许一次 / 拒绝」。</li><li><strong>以前的会话</strong>：每轮对话都会保存在这台电脑上（最多 50 个、保留 30 天，不上传）。关掉 IDE 再打开，可以在插件的会话列表里找到并接着聊；也可以在命令行里用 <code>flyknit --resume</code> 接着聊。</li><li><strong>思考过程</strong>：默认不开深度思考，回答和过程会成段地显示，不会一个字一个字地刷。确实需要时把参数写成 <code>[&quot;acp&quot;, &quot;--think&quot;]</code>。</li><li><strong>停止</strong>：用插件自己的停止按钮，已经开始的操作会照常收尾。</li></ul><h2 id="不提供的能力" tabindex="-1">不提供的能力 <a class="header-anchor" href="#不提供的能力" aria-label="Permalink to &quot;不提供的能力&quot;">​</a></h2><p>长期记忆、浏览器、连接器、子代理、向你提问——这些需要 FlyknitBuddy 的界面。IDE 自带的 MCP 服务器也不会接入（连接器只认 IT 配置的）。</p><div class="tip custom-block"><p class="custom-block-title">升级</p><p>IDE 开着 FlyknitBuddy 智能体时，FlyknitBuddy 的自动升级会等它退出。要升级时先在 IDE 里断开智能体，或关掉 IDE。</p></div><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>插件显示「not installed」或找不到命令</td><td><code>command</code> 写成带 <code>.exe</code> 的完整路径，完全退出 VS Code 再打开</td></tr><tr><td>连上了但开会话时报「IT 没有开启命令行 / IDE 接入」</td><td>找 IT 在安全中心打开</td></tr><tr><td>报「还没登录」</td><td>打开桌面端 FlyknitBuddy 登录一次</td></tr><tr><td>很慢</td><td>确认没加 <code>--think</code>；读很多文件的任务（比如分析整个项目）本身要几分钟，面板里能看到每一步在做什么</td></tr><tr><td>会话列表是空的</td><td>只有升级后的新会话才会保存；会话按项目文件夹分开，换了文件夹列表不一样</td></tr></tbody></table>`,28)])])}const E=i(n,[["render",l]]);export{c as __pageData,E as default};
